import{_ as d,o as r,c as o,ae as a}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-面向对象-UML建模","description":"","frontmatter":{"title":"架构师-备考 综合知识-面向对象-UML建模"},"headers":[],"relativePath":"综合知识/面向对象/UML建模.md","filePath":"综合知识/面向对象/UML建模.md"}'),n={name:"综合知识/面向对象/UML建模.md"};function e(s,t,h,l,i,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] UML 结构（构造块/规则/公共机制）</li><li>[x] 四种关系（依赖/关联/泛化/实现）+ 聚集 vs 组合</li><li>[x] 类关系（关联/聚集/组合/泛化/依赖）</li><li>[x] 静态图（类图/对象图/用例图/构件图/部署图）</li><li>[x] 动态图（序列图/通信图/状态图/活动图）</li><li>[x] 4+1 视图模型（逻辑/进程/实现/部署/用例）</li><li>[x] 用例关系（包含/扩展/泛化）</li><li>[x] OO 建模过程（用例模型→分析模型→设计模型）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、uml-概述-★" tabindex="-1">一、UML 概述 ★ <a class="header-anchor" href="#一、uml-概述-★" aria-label="Permalink to &quot;一、UML 概述 ★&quot;">​</a></h3><blockquote><p>UML（统一建模语言）是<strong>可视化的建模语言，而非程序设计语言</strong>，支持从需求分析开始的软件开发全过程。</p></blockquote><p><strong>UML 三大结构：</strong></p><table tabindex="0"><thead><tr><th>组成部分</th><th>说明</th></tr></thead><tbody><tr><td><strong>构造块</strong></td><td>事物（thing）+ 关系（relationship）+ 图（diagram）</td></tr><tr><td><strong>规则</strong></td><td>构造块如何放在一起的规定</td></tr><tr><td><strong>公共机制</strong></td><td>达到特定目标的公共 UML 方法</td></tr></tbody></table><hr><h3 id="二、四种关系-★" tabindex="-1">二、四种关系 ★ <a class="header-anchor" href="#二、四种关系-★" aria-label="Permalink to &quot;二、四种关系 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关系</th><th>说明</th><th>UML 表示</th></tr></thead><tbody><tr><td><strong>依赖（Dependency）</strong></td><td>一个事物发生变化会影响另一个事物，短暂非持久</td><td>虚线箭头</td></tr><tr><td><strong>关联（Association）</strong></td><td>类之间的某种联系，通常是双向的</td><td>实线</td></tr><tr><td><strong>泛化（Generalization）</strong></td><td>一般与特殊的关系（继承）</td><td>实线空心三角箭头</td></tr><tr><td><strong>实现（Realization）</strong></td><td>类实现接口</td><td>虚线空心三角箭头</td></tr></tbody></table><p><strong>聚集 vs 组合（关联的特殊类型）：</strong></p><table tabindex="0"><thead><tr><th>对比</th><th>聚集（Aggregation）</th><th>组合（Composition）</th></tr></thead><tbody><tr><td>关系强度</td><td>较弱</td><td>较强</td></tr><tr><td>整体-部分</td><td>部分可脱离整体独立存在</td><td>部分<strong>不能脱离整体</strong>单独存在</td></tr><tr><td>示例</td><td>大学→学生（学生可独立存在）</td><td>大学→系（系不能脱离大学）</td></tr></tbody></table><blockquote><p>口诀：<strong>聚集整体散，组合整体断。</strong></p></blockquote><hr><h3 id="三、uml-图分类-★" tabindex="-1">三、UML 图分类 ★ <a class="header-anchor" href="#三、uml-图分类-★" aria-label="Permalink to &quot;三、UML 图分类 ★&quot;">​</a></h3><h4 id="静态图-描述系统静态结构" tabindex="-1">静态图（描述系统静态结构） <a class="header-anchor" href="#静态图-描述系统静态结构" aria-label="Permalink to &quot;静态图（描述系统静态结构）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>图</th><th>说明</th><th>关键记忆</th></tr></thead><tbody><tr><td><strong>类图</strong></td><td>系统的静态设计视图，展现类及其关系</td><td>最核心的静态图</td></tr><tr><td><strong>对象图</strong></td><td>展现某一时刻一组对象及关系</td><td>类图的实例</td></tr><tr><td><strong>用例图</strong></td><td>描述系统功能需求和参与者</td><td>需求分析阶段使用</td></tr><tr><td><strong>构件图（组件图）</strong></td><td>展现一组构件之间的组织和依赖</td><td>物理实现层面</td></tr><tr><td><strong>部署图</strong></td><td>系统静态部署视图，软硬件映射</td><td>拓扑结构、系统安装</td></tr></tbody></table><h4 id="动态图-描述系统动态行为" tabindex="-1">动态图（描述系统动态行为） <a class="header-anchor" href="#动态图-描述系统动态行为" aria-label="Permalink to &quot;动态图（描述系统动态行为）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>图</th><th>说明</th><th>关键记忆</th></tr></thead><tbody><tr><td><strong>序列图（顺序图）</strong></td><td>按时间顺序展示对象间交互</td><td>强调<strong>时间顺序</strong></td></tr><tr><td><strong>通信图（协作图）</strong></td><td>强调参加交互的对象的<strong>组织</strong></td><td>强调对象组织结构</td></tr><tr><td><strong>状态图</strong></td><td>描述对象状态及状态转换</td><td>关注对象生命周期</td></tr><tr><td><strong>活动图</strong></td><td>特殊的状态图，描述活动流程</td><td>类似流程图，支持分支汇合</td></tr></tbody></table><blockquote><p>口诀：<strong>类对用构部 = 静态；序通状活 = 动态。序列看时间，通信看组织。</strong></p></blockquote><hr><h3 id="四、4-1-视图模型-★" tabindex="-1">四、4+1 视图模型 ★ <a class="header-anchor" href="#四、4-1-视图模型-★" aria-label="Permalink to &quot;四、4+1 视图模型 ★&quot;">​</a></h3><blockquote><p>4+1 视图从 5 个视角描述软件架构，5 个视图结合才能反映全部内容。</p></blockquote><table tabindex="0"><thead><tr><th>视图</th><th>关注点</th><th>对应 UML 图</th><th>关心者</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>系统功能需求</td><td>类图、对象图、状态图</td><td>最终用户</td></tr><tr><td><strong>进程视图</strong></td><td>运行特性、并发/分布/容错</td><td>活动图</td><td>系统集成人员</td></tr><tr><td><strong>实现视图</strong>（开发视图）</td><td>软件模块组织管理</td><td>包图、组件图</td><td>程序员</td></tr><tr><td><strong>部署视图</strong>（物理视图）</td><td>软件→硬件映射、拓扑结构</td><td>部署图</td><td>系统工程师</td></tr><tr><td><strong>用例视图</strong>（场景）</td><td>使4个视图有机联系</td><td>用例图</td><td>分析师/测试人员</td></tr></tbody></table><hr><h3 id="五、用例建模-★" tabindex="-1">五、用例建模 ★ <a class="header-anchor" href="#五、用例建模-★" aria-label="Permalink to &quot;五、用例建模 ★&quot;">​</a></h3><p><strong>参与者（Actor）</strong>：与系统交互的外部实体，可以是<strong>人、外部系统、时间、设备</strong>（如打印机）。</p><p><strong>用例关系三种类型：</strong></p><table tabindex="0"><thead><tr><th>关系</th><th>说明</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>包含（Include）</strong></td><td>一个用例<strong>无条件</strong>使用另一个用例的行为</td><td>注册课程<strong>必先</strong>登录系统</td></tr><tr><td><strong>扩展（Extend）</strong></td><td>一个用例在<strong>特定条件下</strong>扩展另一个用例</td><td>不及格<strong>才参加</strong>补考</td></tr><tr><td><strong>泛化（Generalization）</strong></td><td>用例之间的继承关系</td><td>一般用例→特殊用例</td></tr></tbody></table><hr><h3 id="六、oo-建模过程" tabindex="-1">六、OO 建模过程 <a class="header-anchor" href="#六、oo-建模过程" aria-label="Permalink to &quot;六、OO 建模过程&quot;">​</a></h3><blockquote><p>利用 UML 构建三类模型：</p></blockquote><table tabindex="0"><thead><tr><th>模型</th><th>构建方式</th><th>产物</th></tr></thead><tbody><tr><td><strong>用例模型</strong></td><td>分析需求行为，按 OO 原则划分为用例</td><td>用例图 + 顺序图</td></tr><tr><td><strong>分析模型</strong></td><td>在用例基础上抽象类，明确关系构建类图</td><td>类图 + 领域概念模型</td></tr><tr><td><strong>设计模型</strong></td><td>补充状态图/活动图/协作图等描述内部处理细节</td><td>完整 UML 模型</td></tr></tbody></table>',33)])])}const u=d(n,[["render",e]]);export{c as __pageData,u as default};
